\label{thm:largeHunit} $ $ \\ \vspace*{-0.4cm}
\begin{enumerate}[label=(\roman*), ref=(\roman*)]
    \item\label{item:infinitelymany} For $H>\frac14$, $I_k(H)$ is attained infinitely many $k \in \mathbb{Z}$.
    \item\label{item:largeHexistence} There exists $H_0>\tfrac{1}{4}$ such that $I_1(H)$ is attained for every $H\geq H_0$.
\end{enumerate}

\label{lemma:scaling}
Let $\boldsymbol{m}\in H^2(\mathbb{R}^3;\mathbb{S}^2)$. Then there exists $\theta\in [0,1]$ (depending on $\boldsymbol{m}$) such that
\begin{align}
    \label{eq:scalingFormula}
  \inf_{\lambda>0}\mathcal{E}_H[\boldsymbol{m}^{\lambda}]
=
\frac{\sqrt{2}}{3}
\frac{\sqrt{\theta^2+12H}-2\theta}
{\sqrt{\sqrt{\theta^2+12H}-\theta}}
\,
\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}
\|\Delta\boldsymbol{m}\|_{L^2}^{\frac32}.
\end{align}
In particular
\begin{align*}
      \frac{\sqrt{2}}{3}\frac{\sqrt{1+12H}-2}{\sqrt{\sqrt{1+12H}-1}}\,\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}\|\Delta\boldsymbol{m}\|_{L^2}^{\frac32}\le \inf_{\lambda>0}\mathcal{E}_H[\boldsymbol{m}^{\lambda}]\le \frac{\sqrt{2}}{3}(12H)^{\frac14}\,\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}\|\Delta\boldsymbol{m}\|_{L^2}^{\frac32}.
\end{align*}

Define for $\lambda>0$, $\boldsymbol{m}^{\lambda}(x)=\boldsymbol{m}(\lambda x)$ and as in \eqref{eq:scaling}
\begin{align*}
\mathcal{E}_H[\boldsymbol{m}^{\lambda}] &=  \frac{\lambda \| \Delta \boldsymbol{m} \|_{L^2}^2}{2} - \frac{ \|\nabla \boldsymbol{m}\|_{L^2}^2}{2\lambda} + \frac{H\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^2}{2\lambda^3}\\
&=\frac12
\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}
\|\Delta\boldsymbol{m}\|_{L^2}^{\frac32}
\left(
y-\frac{\theta}{y}+\frac{H}{y^3}
\right),
\end{align*}
where (assuming $\boldsymbol{m} \neq \boldsymbol{\hat{e}}_{3}$)
\begin{align*}
y
=
\lambda
\frac{\|\Delta\boldsymbol{m}\|_{L^2}^{\frac12}}
{\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}},
\qquad
\theta
=
\frac{\|\nabla\boldsymbol{m}\|_{L^2}^{2}}
{\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}\|\Delta\boldsymbol{m}\|_{L^2}} \in [0,1].
\end{align*}
The minimum in $y>0$ is attained at
\begin{align*}
y =\sqrt \frac{\sqrt{\theta^2+12H}-\theta}{2}.
\end{align*}
Since $\inf_{\lambda>0} \mathcal{E}_H[\boldsymbol{m}^\lambda]$ is decreasing in $\theta$, the desired estimates follow.

\label{lemma:scaling_invariant_topological_bound}
Let $\boldsymbol{m}\in H^2(\mathbb{R}^3;\mathbb{S}^2)$. Then
\begin{align*}
    \|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}
    \|\Delta\boldsymbol{m}\|_{L^2}^{\frac32}
    \ge
    2^4 3^{\frac38}\pi^2 |Q[\boldsymbol{m}]|^{\frac34}.
\end{align*}

We use the Whitehead representation
\begin{align*}
    Q[\boldsymbol{m}]
    =
    \frac{1}{16\pi^2}
    \int_{\mathbb{R}^3}
    \boldsymbol{A}\cdot\boldsymbol{F}
    \mathrm{d}x,
    \qquad
    \nabla \times \boldsymbol{A}=\boldsymbol{F},
    \qquad
    \nabla \cdot \boldsymbol{A}=0.
\end{align*}
By Hölder's inequality,
\begin{align*}
    |Q[\boldsymbol{m}]|
    \le
    \frac{1}{16\pi^2}
    \|\boldsymbol{A}\|_{L^6}
    \|\boldsymbol{F}\|_{L^{\frac65}}.
\end{align*}
In Coulomb gauge and by the sharp Sobolev inequality on $\mathbb{R}^3$ (cf. \cite{Talenti1976BestSobolevConstant}),
\begin{align*}
    \|\boldsymbol{A}\|_{L^6}
    \le
    \frac{2^{\frac23}}{\sqrt{3}\pi^{\frac23}}
    \|\nabla\boldsymbol{A}\|_{L^2}
    =
    \frac{2^{\frac23}}{\sqrt{3}\pi^{\frac23}}
    \|\boldsymbol{F}\|_{L^2}.
\end{align*}
and Hölder interpolation $L^1\cap L^2\subset L^{\frac65}$ yield
\begin{align*}
    |Q[\boldsymbol{m}]| \le \frac{2^{\frac23}}{16\sqrt{3}\pi^{\frac83}} \|\boldsymbol{F}\|_{L^1}^{\frac23} \|\boldsymbol{F}\|_{L^2}^{\frac43}.
\end{align*}
As in the Vakulenko-Kapitanskii-type estimate used by Ward \cite{Ward1999Hopfions}, and with $ \boldsymbol{m}\cdot\Delta\boldsymbol{m}=-|\nabla\boldsymbol{m}|^2$, one has
\begin{align*}
    |\boldsymbol{F}| \le \frac12|\nabla\boldsymbol{m}|^2 \quad \text{and} \quad |\boldsymbol{F}| \le \frac12|\Delta\boldsymbol{m}|.
\end{align*}
Hence, we obtain the intermediate estimate
\begin{align}
    \label{eq:intermediateVK}
    |Q[\boldsymbol{m}]|^{\frac34}
    \le
    \frac{1}{2^4 3^{\frac38}\pi^2}
    \|\nabla\boldsymbol{m}\|_{L^2}
    \|\Delta\boldsymbol{m}\|_{L^2}.
\end{align}
Finally, using integration by parts yields
\begin{align*}
|Q[\boldsymbol{m}]|^{\frac34} \le \frac{1}{2^4 3^{\frac38}\pi^2} \|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12} \|\Delta\boldsymbol{m}\|_{L^2}^{\frac32}.
\end{align*}

\label{lemma:loc}
Let $B \subset \mathbb{R}^3$ be measurable and let $\boldsymbol{m} \in H^2(\mathbb{R}^3;\mathbb{S}^2)$. There exist constants $C_0, C_1 > 0$, independent of $\boldsymbol{m}$ and $B$, such that
\begin{align*}
\int_B |\boldsymbol{F} \cdot \boldsymbol{A}|  \mathrm{d}x  &\le C_0 \mathcal{E}_H[\boldsymbol{m}] |B|^{\frac13},\\[0.5em]
\int_B |\boldsymbol{F} \cdot \boldsymbol{A}|  \mathrm{d}x  &\le C_1 \mathcal{E}_H[\boldsymbol{m}]^{\frac76} \mathcal{E}_H[\boldsymbol{m};B]^{\frac16},
\end{align*}
where $\boldsymbol{A}\in L^6(\mathbb{R}^3;\mathbb{R}^3)$ is chosen in Coulomb gauge, i.e. $\nabla \cdot \boldsymbol{A} = 0$.

Using the same estimates as in the proof of Lemma~\ref{lemma:scaling_invariant_topological_bound}, applied locally on $B$ where appropriate, we obtain
\begin{align*}
\int_B |\boldsymbol{F}\cdot\boldsymbol{A}|\mathrm{d}x
\lesssim \|\nabla \boldsymbol{m}\|_{L^2(B)}^{\frac43}\|\nabla \boldsymbol{m} \|_{L^4(B)}^{\frac23}\|\nabla \boldsymbol{m}\|_{L^4(\mathbb{R}^3)}^2.
\end{align*}
Thus 
\begin{align*}
    \|\nabla \boldsymbol{m}\|_{L^2(B)}^{\frac43} \le c |B|^{\frac13} \| \nabla \boldsymbol{m}\|_{L^4(B)}^{\frac43} \quad \text{ and } \quad  \|\nabla \boldsymbol{m}\|_{L^4(\mathbb{R}^3)}^4 \lesssim \mathcal{E}_H[\boldsymbol{m}]
\end{align*}
yield the first inequality. To obtain the second estimate, we use 
\begin{align*}
\| \nabla \boldsymbol{m}\|_{L^4(B)}^{\frac23}\lesssim \mathcal{E}_H[\boldsymbol{m};B]^{\frac16} \quad \text{ and } \quad \| \nabla \boldsymbol{m}\|_{L^2(\mathbb{R}^3)}^2 \lesssim \mathcal{E}_H[\boldsymbol{m}].
\end{align*}

\label{lemma:energygrowth}
There exists a constant $C>0$ such that for all $k\in\mathbb{Z}$ and $H>\tfrac14$,
\begin{align*}
I_k(H) \le CH^{\frac14}|k|^{\frac34}.
\end{align*}

We may assume $k>0$. Choose $\ell\in\mathbb{N}$ such that
\begin{align*}
\ell^{2} \le k < (\ell+1)^{2}.
\end{align*}
By \cite{LinYang2004}, there exist maps $\overline{\boldsymbol{m}},\boldsymbol{m}_{0}\in H^{2}(\mathbb{R}^{3};\mathbb{S}^{2})$ satisfying
\begin{align*}
\overline{\boldsymbol{m}}=\boldsymbol{\hat{e}}_{3} \text{ on } \mathbb{R}^{3}\setminus B_{\sqrt{\ell}}, \quad Q[\overline{\boldsymbol{m}}]=\ell^{2}, \\
\boldsymbol{m}_{0}=\boldsymbol{\hat{e}}_{3} \text{ on } \mathbb{R}^{3}\setminus B_{1},\quad Q[\boldsymbol{m}_{0}]=1,
\end{align*}
and a constant $C>0$ such that
\begin{align*}
\|\nabla^{2}\overline{\boldsymbol{m}}\|_{L^{\infty}} \le C, \quad \|\nabla^{2}\boldsymbol{m}_{0}\|_{L^{\infty}} \le C.
\end{align*}
Define $\boldsymbol{m}\in H^{2}(\mathbb{R}^{3};\mathbb{S}^{2})$ by setting $\boldsymbol{m}=\overline{\boldsymbol{m}}$ on $B_{\sqrt{\ell}}$ and placing $(k-\ell^{2})$ translated copies of $\boldsymbol{m}_{0}$ at points $x_{1},\dots,x_{k-\ell^{2}}$ with
\begin{align*}
|x_{i}-x_{j}|\gg 3,\quad |x_{i}|\gg\sqrt{\ell}+1.
\end{align*}
Exploiting the quasi-locality of the Hopf index density (in Coulomb gauge), the supports may be chosen sufficiently far apart so that
\begin{align*}
Q[\boldsymbol{m}] = \ell^{2} + (k-\ell^{2}) = k.
\end{align*}
Lemma~\ref{lemma:scaling}, together with Young's inequality, then yields
\begin{align*}
   I_k(H) \le  \inf_{\lambda >0}\mathcal{E}_H[\boldsymbol{m}^{\lambda}] \lesssim H^{\frac14}\int_{\mathbb{R}^3} |\nabla^2 \boldsymbol{m}|^2 + |\boldsymbol{m} - \boldsymbol{\hat{e}}_{3}|^2 \mathrm{d}x .
\end{align*}
Using disjointness of supports and the uniform bounds on $\nabla^{2}\overline{\boldsymbol{m}}$ and $\nabla^{2}\boldsymbol{m}_{0}$, together with $|B_{\sqrt{\ell}}|=|B_1|  \ell^{\frac32}$ and $0 \le k-\ell^{2}\le 2\ell+1$, we obtain
\begin{align*}
I_k(H) \lesssim H^{\frac14}(\ell^{\frac32} + \ell)\lesssim H^{\frac14} k^{\frac34}.
\end{align*}

\label{lemma:vanishing}
Let $(\boldsymbol{m}_n)_{n \in \mathbb{N}}$ be a minimizing sequence for $I_k(H)$ with $k\in\mathbb Z\setminus\{0\}$.
Then, alternative~\ref{case:vanishing} vanishing cannot occur.

In the vanishing case, interior elliptic estimates yield
\begin{align*}
    \|\boldsymbol{m}_n - \boldsymbol{\hat{e}}_{3}\|_{H^2(B_1(y))}^2\lesssim \int_{B_2(y)} |\Delta \boldsymbol{m}_n|^2 + |\boldsymbol{m}_n - \boldsymbol{\hat{e}}_{3}|^2 \mathrm{d}x 
\end{align*}
for every $y \in \mathbb{R}^3.$ Moreover, $H^2_{\mathrm{loc}}\hookrightarrow C^0_{\mathrm{loc}}$ implies
\begin{align*}
\|\boldsymbol{m}_n-\boldsymbol{\hat{e}}_{3}\|_{L^\infty(\mathbb{R}^3)} =\sup_{y \in \mathbb{R}^3}\|\boldsymbol{m}_n-\boldsymbol{\hat{e}}_{3}\|_{L^\infty(B_1(y))}\lesssim \sup_{y \in \mathbb{R}^3}\|\boldsymbol{m}_n-\boldsymbol{\hat{e}}_{3}\|_{H^2(B_1(y))}\to 0. 
\end{align*}
Hence $\boldsymbol{m}_n$ is null-homotopic for large $n\in \mathbb{N}$, contradicting $Q[\boldsymbol{m}_n]=k\neq0$.

\label{cut-offconstruction}
There exists a $\varepsilon_0 > 0$ such that if for $0<\varepsilon<\varepsilon_0$, $R \geq 1$ and $\boldsymbol{m} \in H^2(\mathbb{R}^3;\mathbb{S}^2)$ we have
\begin{align*}
\int_{B_{4R}\setminus B_R} |\boldsymbol{m}- \boldsymbol{\hat{e}}_{3}|^2 + |\Delta \boldsymbol{m}|^2 \mathrm{d}x \le \varepsilon,
\end{align*}
then we can find $\boldsymbol{m}^{(1)}$ and $\boldsymbol{m}^{(2)}$ with the following properties:
\begin{align*}
&\boldsymbol{m}^{(1)} = \boldsymbol{m} \text{ on } B_{2R}  &&\boldsymbol{m}^{(2)} = \boldsymbol{m} \text{ on } \mathbb{R}^3 \setminus B_{2R} \\
&\boldsymbol{m}^{(1)} = \boldsymbol{\hat{e}}_{3} \text{ on } \mathbb{R}^3 \setminus B_{4R} &&\boldsymbol{m}^{(2)} = \boldsymbol{\hat{e}}_{3} \text{ on }  B_{R} \\
\end{align*}	
and, furthermore, there is a constant $c>0$ with
\begin{align*}
\lVert \boldsymbol{m}^{(1)} - \boldsymbol{\hat{e}}_{3} \rVert_{H^2(\mathbb{R}^3 \setminus B_{2R})}^2 + \lVert \boldsymbol{m}^{(2)} - \boldsymbol{\hat{e}}_{3} \rVert_{H^2(B_{2R})}^2 \le c \varepsilon.
\end{align*}

We construct only $\boldsymbol{m}^{(1)}$. The construction of $\boldsymbol{m}^{(2)}$ is analogous.
By the interior elliptic estimate on annuli, applied after scaling, we have
\begin{align*}
    \|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{H^2(B_{3R}\setminus B_{2R})}^2
    \le
    C
    \int_{B_{4R}\setminus B_R}
    |\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}|^2+|\Delta\boldsymbol{m}|^2 \mathrm{d}x ,
\end{align*}
where $C$ is independent of $R\geq 1$. Here one covers $B_{3R}\setminus B_{2R}$ by balls adapted to the scale $R$ and applies the standard interior elliptic estimate on slightly larger balls. The overlap is uniformly bounded, so the constant is independent of $R\geq 1$. Hence, by the assumption,
\begin{align*}
    \|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{H^2(B_{3R}\setminus B_{2R})}^2
    \le C\varepsilon .
\end{align*}
By Sobolev embedding, after decreasing $\varepsilon_0$ if necessary, we may assume
\begin{align*}
    |\bar m|\le \frac{1}{\sqrt{2}},
    \qquad
    m_3\geq \frac{1}{\sqrt{2}}
    \qquad
    \text{on } B_{3R}\setminus B_{2R},
\end{align*}
where $\bar m=(m_1,m_2)$. Thus on this annulus
\begin{align*}
    \boldsymbol{m}
    =
    \bigl(\bar m,\sqrt{1-|\bar m|^2}\,\bigr).
\end{align*}

Let $\eta\in C^\infty([0,\infty))$ satisfy
\begin{align*}
    0\le \eta\le 1,
    \qquad
    \eta(t)=1 \text{ for } t\le 2
    \quad \text{ and } \quad
    \eta(t)=0 \text{ for } t\geq 3 .
\end{align*}
Set
\begin{align*}
    \eta_R(x)=\eta\left(\frac{|x|}{R}\right).
\end{align*}
Then
\begin{align*}
    |\nabla^j\eta_R|\le C R^{-j},
    \qquad
    j=1,2 .
\end{align*}
We define
\begin{align*}
    \boldsymbol{m}^{(1)}(x)
    =
    \begin{cases}
        \boldsymbol{m}(x),
        & x\in B_{2R},
        \\
        \left(
        \eta_R(x)\bar m(x),
        \sqrt{1-|\eta_R(x)\bar m(x)|^2}
        \right),
        & x\in B_{3R}\setminus B_{2R},
        \\
        \boldsymbol{\hat{e}}_{3},
        & x\in \mathbb{R}^3\setminus B_{3R}.
    \end{cases}
\end{align*}
This is well defined because $|\eta_R\bar m|\le 1/\sqrt{2}$. Moreover
\begin{align*}
    \boldsymbol{m}^{(1)}=\boldsymbol{m} \text{ on } B_{2R},
    \qquad
    \boldsymbol{m}^{(1)}=\boldsymbol{\hat{e}}_{3} \text{ on } \mathbb{R}^3\setminus B_{3R}.
\end{align*}
Let
\begin{align*}
    \Psi(u)=\bigl(u,\sqrt{1-|u|^2}\,\bigr).
\end{align*}
On $\{|u|\le 1/\sqrt{2}\}$ the map $\Psi$ has bounded $C^2$ norm. Since
$\boldsymbol{m}^{(1)}=\boldsymbol{\hat{e}}_{3}$ on $\mathbb{R}^3\setminus B_{3R}$, we have
\begin{align*}
    \|\boldsymbol{m}^{(1)}-\boldsymbol{\hat{e}}_{3}\|_{H^2(\mathbb{R}^3\setminus B_{2R})}^2
    =
    \|\boldsymbol{m}^{(1)}-\boldsymbol{\hat{e}}_{3}\|_{H^2(B_{3R}\setminus B_{2R})}^2 
\end{align*}
and $\boldsymbol{m}^{(1)} - \boldsymbol{\hat{e}}_{3} = \Psi(\eta_R \bar m) - \Psi(0)$ on $B_{3R}\setminus B_{2R}$. Therefore, using the bounds on $\eta_R$ and $R\geq 1$, we have
\begin{align*}
    \|\boldsymbol{m}^{(1)}-\boldsymbol{\hat{e}}_{3}\|_{H^2(\mathbb{R}^3\setminus B_{2R})}^2
    &\le
    C\|\eta_R\bar m\|_{H^2(B_{3R}\setminus B_{2R})}^2 \le
    C\|\bar m\|_{H^2(B_{3R}\setminus B_{2R})}^2
    \\
    &\le
    C\|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{H^2(B_{3R}\setminus B_{2R})}^2 \le C\varepsilon .
\end{align*}
This proves the desired estimate for $\boldsymbol{m}^{(1)}$.

\label{lemma:dichotomy}
Let $H>\frac14$ and $k \in \mathbb{Z} \setminus \{0\}$. Assume further there exists a minimizing sequence $(\boldsymbol{m}_n)_{n \in \mathbb{N}}$ for $I_k(H)$ such that condition~\ref{case:dichotomy} dichotomy is satisfied. Then there exists $\ell \in \mathbb{Z} \setminus\{0,k\}$ with
\begin{align*}
I_k(H) \geq I_\ell(H) + I_{k-\ell}(H).
\end{align*}

\label{prop:existence}
Let $H>\frac14$ and $k \in \mathbb{Z}$. If for all $\ell \in \mathbb{Z} \setminus \{ 0,k \}$ 
\begin{align*}
I_k(H) < I_\ell(H) + I_{k-\ell}(H),
\end{align*}
then $I_k(H)$ is attained.

Let $(\boldsymbol{m}_n)_{n \in \mathbb{N}} \subset H^2(\mathbb{R}^3;\mathbb{S}^2)$ be a minimizing sequence and assume without loss of generality $k \neq 0$. Using Lemma~\ref{lemma:vanishing} and Lemma~\ref{lemma:dichotomy}, $(e(\boldsymbol{m}_n))_{n \in \mathbb{N}}$, up to some subsequence, can only satisfy the compactness condition~\ref{case:compactness}. By translation invariance of $\mathcal E$ and $Q$ we may assume the concentrating centers are at the origin, i.e. for every $\varepsilon>0$ there exists $R>0$ such that
\begin{align} \label{eq:tightness}
\int_{\mathbb R^3\setminus B_R} e(\boldsymbol{m}_n)\mathrm{d}x \le \varepsilon
\quad \text{for all large } n .
\end{align}
The coercivity estimate \eqref{eq:densityCoercivity}, together with the elliptic estimate on $\mathbb{R}^3$, gives
\begin{align*}
\|\boldsymbol{m}_n - \boldsymbol{\hat{e}}_{3}\|_{H^2(\mathbb R^3)}^2 \le C \mathcal{E}_H[\boldsymbol{m}_n] \le C M .
\end{align*}
Since $H^2$ is reflexive there is a map $\boldsymbol{m}:\mathbb{R}^3 \to \mathbb{R}^3$ such that $\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\in H^2(\mathbb R^3;\mathbb R^3)$ with
\begin{align*}
\boldsymbol{m}_n - \boldsymbol{\hat{e}}_{3} \rightharpoonup \boldsymbol{m} - \boldsymbol{\hat{e}}_{3} \quad \text{in } H^2(\mathbb R^3) .
\end{align*}
By Rellich on bounded sets together with \eqref{eq:tightness}, we also have
\begin{align*}
\boldsymbol{m}_n - \boldsymbol{\hat{e}}_{3} \to \boldsymbol{m} - \boldsymbol{\hat{e}}_{3} \quad \text{in } H^1(\mathbb R^3).
\end{align*}
and hence, up to a subsequence,
\begin{align*}
\boldsymbol{m}_n \to \boldsymbol{m} \quad \text{and} \quad \nabla \boldsymbol{m}_n \to \nabla \boldsymbol{m} \quad \text{almost everywhere in } \mathbb R^3 .
\end{align*}
In particular $\boldsymbol{m}(x)\in \mathbb S^2$ almost everywhere, hence $\boldsymbol{m}\in H^2(\mathbb R^3;\mathbb S^2)$. Interpolating the strong $H^1$ convergence with the weak $H^2$ convergence also yields
\begin{align*}
    \|\boldsymbol{m}_n - \boldsymbol{m}\|_{H^s(\mathbb{R}^3)} \le\|\boldsymbol{m}_n - \boldsymbol{m}\|_{H^1(\mathbb{R}^3)}^{2-s}  \|\boldsymbol{m}_n - \boldsymbol{m}\|_{H^2(\mathbb{R}^3)}^{s-1}\to 0
\end{align*}
as $n\to \infty$ for every $1<s<2$. Furthermore, for $s>\frac32$, we conclude uniform convergence, hence $Q[\boldsymbol{m}]=Q[\boldsymbol{m}_n]=k$ for large $n \in \mathbb{N}$. Lastly, the energy is weakly lower semicontinuous
\begin{align*}
\mathcal{E}_H[\boldsymbol{m}] \le \liminf_{n\to\infty} \mathcal{E}_H[\boldsymbol{m}_n] = I_k(H) .
\end{align*}

\label{cor:minimalenergy}
Let $H>\frac14$. There exists a minimal energy level, that is $k_0=k_0(H)\in\mathbb{Z}\setminus\{0\}$ with
\begin{align*}
I_{k_{0}}(H)=\inf\{I_k(H):k\in\mathbb{Z}\setminus\{0\}\},
\end{align*}
and this infimum is attained.

Choose $ k_1\in\mathbb{N}$ with $I_1(H)<C(H) k_1^{\frac34}$. Then for all $|\ell|> k_1$,
\begin{align*}
I_\ell(H)\ge C (H)|\ell|^{\frac34}>I_1(H).
\end{align*}
Hence
\begin{align*}
\inf\limits_{k \in \mathbb{Z} \setminus \{ 0 \} } I_k(H) = \inf\limits_{k \in \{ -k_1, \dots , k_1 \} \setminus \{ 0 \} }  I_k(H).
\end{align*}
so there is $k_{0}\in\mathbb{Z}\setminus\{0\}$ with $I_{k_{0}}(H)=\inf_{k\ne0}I_k(H)$. Therefore, for $\ell \in \mathbb{Z} \setminus \{0,k_0\}$, we get
\begin{align*}
I_{k_0}(H) < 2 I_{k_0}(H) \le I_\ell(H) +I_{k_0-\ell}(H).
\end{align*}
With Proposition~\ref{prop:existence} we obtain the claim.

\label{EnDec}
Let $H>\frac14$. For every $k \in \mathbb{Z}\setminus\{0\}$ there exist $J \in \mathbb{N}$ and $d_{1},\dots,d_{J} \in \Sigma_H$ with $k=\sum_{i=1}^{J} d_{i}$ such that
\begin{align*}
I_k(H) \ge \sum_{i=1}^{J} I_{d_i}(H).
\end{align*}

Fix $k \in \mathbb{Z}$. If $k \in \Sigma_H$ the statement is immediate with $J=1$ and $d_{1}^{(1)}=k$. Assume $k \notin \Sigma_H$. By \eqref{eq:SigmaH} there exist nonzero integers $d^{(2)}_{1},d^{(2)}_{2}$ with
\begin{align*}
k = d^{(2)}_{1} + d^{(2)}_{2}, \qquad I_k(H) \ge I_{d^{(2)}_{1}}(H) + I_{d^{(2)}_{2}}(H).
\end{align*}
If both $d^{(2)}_{1}$ and $d^{(2)}_{2}$ lie in $\Sigma_H$, the proof is complete. Otherwise, choose the smallest $i \in \{1,2\}$ with $d^{(2)}_{i}\notin \Sigma_H$. We then apply \eqref{eq:SigmaH} again to decompose $d^{(2)}_{i}$ into two nonzero integers. After $J$ refinement steps this yields a finite family of nonzero integers
\begin{align*}
\left( d^{(J)}_{i} \right)_{1 \le i \le J}
\end{align*}
such that
\begin{align*}
k = \sum_{i=1}^{J} d^{(J)}_{i}, \qquad
I_k(H) \ge  \sum_{i=1}^{J} I_{d^{(J)}_i}(H).
\end{align*}
Using
\begin{align*}
I_d(H) \ge C(H)|d|^{\frac34} \ge C(H) \quad \text{for every nonzero } d \in \mathbb{Z},
\end{align*}
we infer
\begin{align*}
I_k(H) \ge JC(H).
\end{align*}
By Lemma~\ref{lemma:energygrowth}, $I_k(H) \le C|k|^{\frac34}$, which implies
\begin{align*}
J \le \frac{I_k(H)}{C(H)}  \le \frac{C}{C(H)}|k|^{\frac34}.
\end{align*}
Thus the refinement terminates after finitely many steps, which proves the claim.

Fix $H>\frac14$ and assume for contradiction that $|\Sigma_H|<\infty$. Set
\begin{align*}
K = \max_{d \in \Sigma_H} |d|.
\end{align*}
Let $k \in \mathbb{Z}$. By Lemma~\ref{EnDec} there exist $J \in \mathbb{N}$ and $d_1,\dots,d_J \in \Sigma_H$ with
\begin{align*}
k=\sum_{i=1}^{J} d_{i}, \qquad I_k(H) \ge \sum_{i=1}^{J} I_{d_i}(H).
\end{align*}
The topological lower bound implies $I_{d_i}(H) \ge C(H)$ for every $1 \le i\le J$, hence
\begin{align*}
I_k(H) \ge JC(H).
\end{align*}
On the other hand,
\begin{align*}
|k| \le \sum_{i=1}^{J} |d_{i}| \le K J \le \frac{K}{C(H)} I_k(H).
\end{align*}
Using Lemma~\ref{lemma:energygrowth}, $I_k(H) \le C|k|^{\frac34}$, we obtain
\begin{align*}
|k| \le \frac{K C}{C(H)}|k|^{\frac34}.
\end{align*}
This gives a contradiction for large $|k|$. Therefore $|\Sigma_H|=\infty$.

\label{lemma:scalinglimit}
Let $\boldsymbol{m}\in H^2(\mathbb{R}^3;\mathbb{S}^2)$. Then
\begin{align}
    \label{eq:scalingLimitFormula}
    \lim_{H \to \infty} \frac{1}{C(H)} \inf_{\lambda >0} \mathcal{E}_H[ \boldsymbol{m}^{\lambda}] = \frac{1}{2^4 3^{\frac38}\pi^2}\| \boldsymbol{m} -\boldsymbol{\hat{e}}_{3} \|_{L^2}^{\frac12}\| \Delta \boldsymbol{m} \|_{L^2}^{\frac32}.
\end{align}

The claim follows by using Lemma~\ref{lemma:scaling}
\begin{align*}
\inf_{\lambda>0}\mathcal{E}_H[\boldsymbol{m}^{\lambda}] = \frac{\sqrt{2}}{3} (12 H)^{\frac14} \|\boldsymbol{m}-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}
\|\Delta\boldsymbol{m}\|_{L^2}^{\frac32}(1+o_H(1))
\end{align*}
and
\begin{align*}
C(H) =  \frac{2^{\frac{9}{2}} \pi^2}{3^{\frac58}}(12H)^{\frac14}(1+o_H(1))
\end{align*}
as $H \to \infty$.

Part~\ref{item:infinitelymany} follows from Proposition~\ref{prop:SigmaHunbound} and by \eqref{eq:SigmaH} together with Proposition~\ref{prop:existence}. For Part~\ref{item:largeHexistence} it suffices to treat the class $k=1$. By Proposition~\ref{prop:existence}, $I_1(H)$ is attained provided
\begin{align*}
    I_1(H) < I_\ell(H)+I_{1-\ell}(H)
    \qquad\text{for all } \ell\in\mathbb{Z}\setminus\{0,1\}.
\end{align*}
For $\ell\in \{-1,2\}$ this is immediate
\begin{align*}
    I_1(H)<I_1(H)+I_2(H)=I_{-1}(H)+I_2(H).
\end{align*}
It therefore remains to verify the inequality for $\ell\in\mathbb{Z}\setminus\{-1,0,1,2\}$. For such $\ell$ the topological lower bound $I_k(H)\ge C(H)|k|^{\frac34}$ \cite{harland} gives
\begin{align*}
    I_\ell(H)+I_{1-\ell}(H)
    \ge C(H)\bigl(|\ell|^{\frac34}+|1-\ell|^{\frac34}\bigr)
    \ge C(H)\bigl(2^{\frac34}+3^{\frac34}\bigr).
\end{align*}
Hence it suffices to show
\begin{align*}
    \frac{I_1(H)}{C(H)} < 2^{\frac34}+3^{\frac34}
    \qquad\text{for all sufficiently large } H.
\end{align*}
Let $\boldsymbol{m}_\ast$ be the unit charge competitor of the preceding subsection. Since $\boldsymbol{m}_\ast^\lambda$ has Hopf index one for every $\lambda>0$, we have $I_1(H)\le\inf_{\lambda>0}\mathcal{E}_H[\boldsymbol{m}_\ast^\lambda]$, and Lemma~\ref{lemma:scalinglimit} yields
\begin{align*}
    \limsup_{H\to\infty}\frac{I_1(H)}{C(H)}
    \le \lim_{H\to\infty}\frac{1}{C(H)}\inf_{\lambda>0}\mathcal{E}_H[\boldsymbol{m}_\ast^\lambda]
    = \frac{1}{2^4 3^{\frac38}\pi^2}\|\boldsymbol{m}_\ast-\boldsymbol{\hat{e}}_{3}\|_{L^2}^{\frac12}\|\Delta\boldsymbol{m}_\ast\|_{L^2}^{\frac32}.
\end{align*}
By \eqref{eq:competitor} the right-hand side is strictly below $2^{\frac34}+3^{\frac34}$. Thus there exists $H_0>\tfrac14$ such that $I_1(H)/C(H)<2^{\frac34}+3^{\frac34}$ for all $H\ge H_0$, the strict subadditivity condition holds, and $I_1(H)$ is attained.

\label{lemma:asymptotic}
There exists $c,C>0$, $H_0>\frac14$, such that
\begin{align*} 
c H^{\frac14} \le \|\Delta\boldsymbol{m}_H\|_{L^2(\mathbb{R}^3)}^2
    \le C H^{\frac14} \quad \text{ and } \quad
    c H^{-\frac34} \le \|\boldsymbol{m}_H-\boldsymbol{\hat{e}}_{3}\|_{L^2(\mathbb{R}^3)}^2
    \le C H^{-\frac34}.
    \end{align*}
for every $H \ge H_0$. In particular, for $H \geq H_0$,
\begin{align*}
    c H^{-\frac14} \le \|\nabla\boldsymbol{m}_H\|_{L^2(\mathbb{R}^3)}^2
    \le C H^{-\frac14}.
\end{align*}

By coercivity, both terms are controlled by the energy:
\begin{align*}
    \|\Delta\boldsymbol{m}_H\|_{L^2(\mathbb{R}^3)}^2
    \leq
    C\mathcal{E}_H[\boldsymbol{m}_H]
\end{align*}
and
\begin{align*}
    H\|\boldsymbol{m}_H-\boldsymbol{\hat{e}}_{3}\|_{L^2(\mathbb{R}^3)}^2
    \leq
    C\mathcal{E}_H[\boldsymbol{m}_H].
\end{align*}
Since
\begin{align*}
    \mathcal{E}_H[\boldsymbol{m}_H]\leq CH^{\frac14},
\end{align*}
we immediately obtain
\begin{align*}
    \|\Delta\boldsymbol{m}_H\|_{L^2(\mathbb{R}^3)}^2
    \leq
    CH^{\frac14},
    \qquad
    \|\boldsymbol{m}_H-\boldsymbol{\hat{e}}_{3}\|_{L^2(\mathbb{R}^3)}^2
    \leq
    CH^{-\frac34}.
\end{align*}

It remains to show the corresponding lower bounds. Since $Q[\boldsymbol{m}_H]=1$, Lemma~\ref{lemma:scaling_invariant_topological_bound} gives a constant $c_0>0$, independent of $H$, such that
\begin{align*}
    \|\boldsymbol{m}_H-\boldsymbol{\hat{e}}_{3}\|_{L^2(\mathbb{R}^3)}^{\frac12}
    \|\Delta\boldsymbol{m}_H\|_{L^2(\mathbb{R}^3)}^{\frac32}
    \geq
    c_0.
\end{align*}
Combining the lower bound with the corresponding upper bounds yields the lower bounds in terms of $H$. The usual interpolation (integration by parts and Hölder's inequality) together with \eqref{eq:intermediateVK} yield the corresponding bounds of $\| \nabla \boldsymbol{m}_H\|_{L^2}$.

\label{lemma:energyasymptotic}
For every $H>\frac14$, we have
\begin{align*}
    \frac{\sqrt{1+(12H)^{-1}}-2(12H)^{-\frac12}}
    {\sqrt{\sqrt{1+(12H)^{-1}}-(12H)^{-\frac12}}}
    I_k^\infty
    \le
    \frac{I_k(H)}{H^{\frac14}}
    \le
    I_k^\infty.
\end{align*}
In particular,
\begin{align*}
    \lim_{H\to\infty}\frac{I_k(H)}{H^{\frac14}}
    =
    I_k^\infty.
\end{align*}

Let $H_j\to\infty$ be arbitrary and set
\begin{align*}
    \boldsymbol{u}_j:=\widetilde{\boldsymbol{m}}_{H_j}.
\end{align*}
By the definitions of $\widetilde{\mathcal{E}}_{H_j}$ and $\mathcal{E}^\infty$, we have
\begin{align}
    \mathcal{E}^\infty(\boldsymbol{u}_j)
    &=
    \widetilde{\mathcal{E}}_{H_j}(\boldsymbol{u}_j)
    +
    \frac{1}{2H_j^{\frac12}}
    \|\nabla\boldsymbol{u}_j\|_{L^2(\mathbb{R}^3)}^2
    \notag\\
    &=
    \frac{I_1(H_j)}{H_j^{\frac14}}
    +
    \frac{1}{2H_j^{\frac12}}
    \|\nabla\boldsymbol{u}_j\|_{L^2(\mathbb{R}^3)}^2.
    \label{eq:rescaled_energy_identity}
\end{align}
Thus, by Lemma~\ref{lemma:asymptotic} and Lemma~\ref{lemma:energyasymptotic}, $(\boldsymbol{u}_j)_{j\in\mathbb{N}}$ is a minimizing sequence for $I^\infty_1$.

\label{prop:limitcompactness}
Let $(\boldsymbol{u}_j)_{j\in\mathbb{N}}\subset H^2(\mathbb{R}^3;\mathbb{S}^2)$ with $Q[\boldsymbol{u}_j]=1$ be a minimizing sequence for $I^\infty_1$. Then, after passing to a subsequence, the energy densities $(e^\infty(\boldsymbol{u}_j))_{j\in\mathbb{N}}$ satisfy the compactness alternative~\ref{case:compactness}: there exists a sequence of centers $(y_j)_{j\in\mathbb{N}}\subset\mathbb{R}^3$ such that for every $\varepsilon>0$ there is a radius $R>0$ with
\begin{align*}
    \int_{\mathbb{R}^3\setminus B_R(y_j)}
    e^\infty(\boldsymbol{u}_j)
    \mathrm{d}x
    \le
    \varepsilon
\end{align*}
for $j\in\mathbb{N}$ large enough. In particular, neither vanishing~\ref{case:vanishing} nor dichotomy~\ref{case:dichotomy} occurs.

Since $Q[\boldsymbol{u}_j]=1\neq 0$, vanishing~\ref{case:vanishing} is excluded exactly as in Lemma~\ref{lemma:vanishing}.

Assume dichotomy~\ref{case:dichotomy}. By Lemma~\ref{cut-offconstruction} and the argument of Lemma~\ref{lemma:dichotomy}, applied with $e$ replaced by $e^\infty$, there is an $\ell\in\mathbb{Z}\setminus\{0,1\}$ with
\begin{align*}
    I^\infty_1
    \ge
    I^\infty_\ell
    +
    I^\infty_{1-\ell}.
\end{align*}
We rule this out for every such $\ell$. For $\ell\in\{-1,2\}$ we have $I^\infty_{-1}=I^\infty_1$, hence
\begin{align*}
    I^\infty_\ell+I^\infty_{1-\ell}
    =
    I^\infty_1+I^\infty_2
    >
    I^\infty_1.
\end{align*}
For $\ell\in\mathbb{Z}\setminus\{-1,0,1,2\}$, we use \eqref{eq:limitTopologicalBound} to conclude
\begin{align*}
    I^\infty_\ell+I^\infty_{1-\ell}
    \ge
    c_\infty
    \bigl(
        |\ell|^{\frac34}+|1-\ell|^{\frac34}
    \bigr)
    \ge
    c_\infty
    \bigl(
        2^{\frac34}+3^{\frac34}
    \bigr).
\end{align*}
On the other hand, Lemma~\ref{lemma:energyasymptotic} and \eqref{eq:limitTopologicalBound} give
\begin{align*}
    \frac{I^\infty_1}{c_\infty}
    =
    \lim_{H\to\infty}
    \frac{I_1(H)}{H^{\frac14}}
    \frac{H^{\frac14}}{C(H)}
    =
    \lim_{H\to\infty}
    \frac{I_1(H)}{C(H)},
\end{align*}
which is strictly smaller than $2^{\frac34}+3^{\frac34}$ by \eqref{eq:competitor} and the proof of Theorem~\ref{thm:largeHunit}. Hence $I^\infty_1<I^\infty_\ell+I^\infty_{1-\ell}$ in all cases, a contradiction. Only~\ref{case:compactness} remains.

Part~\ref{item:profileTrivial} was obtained in the discussion preceding Lemma~\ref{lemma:limitproblem}.

For~\ref{item:profileLimit}, let $H_j\to\infty$. By Lemma~\ref{lemma:limitproblem} the sequence $(\widetilde{\boldsymbol{m}}_{H_j})_{j\in\mathbb{N}}$ is a minimizing sequence for $I^\infty_1$ with $Q[\widetilde{\boldsymbol{m}}_{H_j}]=1$, so Proposition~\ref{prop:limitcompactness} provides, after passing to a subsequence, centers $y_j\in\mathbb{R}^3$ such that $\boldsymbol{u}_j=\widetilde{\boldsymbol{m}}_{H_j}(\,\cdot\,-y_j)$ satisfies
\begin{align}
    \label{eq:profileTightness}
    \int_{\mathbb{R}^3\setminus B_R}
    e^\infty(\boldsymbol{u}_j)
    \mathrm{d}x
    \le\varepsilon
    \qquad\text{for all large } j,
\end{align}
where $R=R(\varepsilon)$, and $\mathcal{E}^\infty(\boldsymbol{u}_j)\to I^\infty_1$ by translation invariance.

Since $\|\Delta\boldsymbol{u}_j\|_{L^2}^2+\|\boldsymbol{u}_j-\boldsymbol{\hat{e}}_{3}\|_{L^2}^2=2\mathcal{E}^\infty(\boldsymbol{u}_j)$ and
\begin{align}
    \label{eq:gradientInterpolation}
    \|\nabla \boldsymbol{v}\|_{L^2(\mathbb{R}^3)}^2
    \le
    \|\boldsymbol{v}\|_{L^2(\mathbb{R}^3)}
    \|\Delta \boldsymbol{v}\|_{L^2(\mathbb{R}^3)}
    \qquad\text{for } \boldsymbol{v}\in H^2(\mathbb{R}^3;\mathbb{R}^3),
\end{align}
the elliptic estimate on $\mathbb{R}^3$ shows that $(\boldsymbol{u}_j-\boldsymbol{\hat{e}}_{3})_{j\in\mathbb{N}}$ is bounded in $H^2$. Hence, along a further subsequence, $\boldsymbol{u}_j-\boldsymbol{\hat{e}}_{3}\rightharpoonup\boldsymbol{u}-\boldsymbol{\hat{e}}_{3}$ in $H^2(\mathbb{R}^3;\mathbb{R}^3)$ for some $\boldsymbol{u}$, and by Rellich $\boldsymbol{u}_j\to\boldsymbol{u}$ in $H^1_{\mathrm{loc}}(\mathbb{R}^3)$ and almost everywhere, so that $\boldsymbol{u}\in H^2(\mathbb{R}^3;\mathbb{S}^2)$. Combining \eqref{eq:profileTightness} with the local convergence gives $\boldsymbol{u}_j-\boldsymbol{\hat{e}}_{3}\to\boldsymbol{u}-\boldsymbol{\hat{e}}_{3}$ in $L^2(\mathbb{R}^3)$, and \eqref{eq:gradientInterpolation} applied to $\boldsymbol{v}=\boldsymbol{u}_j-\boldsymbol{u}$ upgrades this to strong convergence in $H^1(\mathbb{R}^3)$.

Exactly as in the proof of Proposition~\ref{prop:existence}, the weak convergence in $H^2(\mathbb{R}^3)$ together with the strong convergence in $H^1(\mathbb{R}^3)$ yields uniform convergence, hence $Q[\boldsymbol{u}]=1$. Weak lower semicontinuity then yields
\begin{align*}
    \mathcal{E}^\infty(\boldsymbol{u}) \le \liminf_{j\to\infty} \mathcal{E}^\infty(\boldsymbol{u}_j) =I^\infty_1,
\end{align*}
so $\boldsymbol{u}$ is a minimizer. Finally, $\|\boldsymbol{u}_j-\boldsymbol{\hat{e}}_{3}\|_{L^2}\to\|\boldsymbol{u}-\boldsymbol{\hat{e}}_{3}\|_{L^2}$ and $\mathcal{E}^\infty(\boldsymbol{u}_j)\to \mathcal{E}^\infty(\boldsymbol{u})$ force $\|\Delta\boldsymbol{u}_j\|_{L^2}\to\|\Delta\boldsymbol{u}\|_{L^2}$, which together with $\Delta\boldsymbol{u}_j\rightharpoonup\Delta\boldsymbol{u}$ in $L^2(\mathbb{R}^3)$ gives $\Delta\boldsymbol{u}_j\to\Delta\boldsymbol{u}$ strongly in $L^2(\mathbb{R}^3)$. Hence $\boldsymbol{u}_j - \boldsymbol{\hat{e}}_{3}\to\boldsymbol{u} - \boldsymbol{\hat{e}}_{3}$ in $H^2(\mathbb{R}^3;\mathbb{R}^3)$.

Let $F\in C^2(0,\infty)$, and let $P$ be a homogeneous polynomial of degree $\ell$ on $\mathbb{R}^3$. Then, for $x\neq 0$ and $r=|x|$,
\begin{align*}
    \Delta\left(
        F(r)\frac{P(x)}{r^\ell}
    \right)
    =
    (D_\ell F)(r)\frac{P(x)}{r^\ell}
    +
    F(r)\frac{\Delta P(x)}{r^\ell},
\end{align*}
where
\begin{align*}
    D_\ell F
    :=
    F''
    +
    \frac{2}{r}F'
    -
    \frac{\ell(\ell+1)}{r^2}F .
\end{align*}

Using the elementary differentiation rules for radial functions together with
\begin{align*}
    x\cdot\nabla P=\ell P,
\end{align*}
the claim follows immediately.

For $\boldsymbol{m}$ as in \eqref{eq:mAnsatz}, we have in spherical coordinates
\begin{align*}
    |\nabla \boldsymbol{m}|^2 = 4 f'(r)^2 \sin^2 \theta  + 4 \frac{\sin^2 f(r)}{r^2} (1+\cos^2 \theta).
\end{align*}
In particular, for $f(r) = 2 \arctan \frac{e^{-r}}{r}$
\begin{align*}
    \int_{\mathbb{R}^3} |\nabla \boldsymbol{m}|^2 \mathrm{d}x = \int_0^{\infty} \mathcal{I}_1(r) \mathrm{d}r
\end{align*}
with \begin{align*}
    \mathcal{I}_1 (r) = \frac{128 \pi}{3} \left( \frac{(r^2+2r+3)r^2 e^{2r}}{(1+r^2 e^{2r})^2}\right).
\end{align*}
